#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using UnityEngine;
using UnityEngine.InputSystem;
public sealed class B04PresentationVerifier:N5Runner
{
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Init()=>N5Args.Start<B04PresentationVerifier>("-verify-b04-av");
 void Place(Vector2 p){Player.ClearTransientInput();Body.position=p;Player.transform.position=p;Body.linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 IEnumerator Enter(string id,string spawn="Entry"){Check(RoomSession.Instance.RequestTransition(id,"Assets/Scenes/"+id+".unity",spawn),"presentation fixture "+id);yield return Ready();yield return new WaitForSeconds(.15f);}
 int Total(PresentationBootstrap av){int n=0;foreach(int v in av.Plays.Values)n+=v;return n;}
 protected override IEnumerator Tests(){yield return NewGame();yield return new WaitForSeconds(.2f);var av=PresentationBootstrap.Instance;bool candidate=N5Args.Has("-b04-expect-av1");Check((av!=null)==candidate,"runtime presentation matches build");var shape=Player.GetComponent<BoxCollider2D>();Vector2 size=shape.size,offset=shape.offset;Vector3 scale=Player.transform.localScale;
  yield return Keys(Key.RightArrow);yield return new WaitForSeconds(.25f);yield return Keys();yield return Keys(Key.Z);yield return new WaitForSeconds(.25f);yield return Keys();yield return new WaitForSeconds(.7f);
  RoomSession.Instance.GrantDash();RoomSession.Instance.GrantDoubleJump();yield return new WaitForSeconds(.2f);yield return Tap(Key.C);yield return new WaitForSeconds(.25f);yield return Tap(Key.X);
  yield return Enter("A04","FromLeft");var enemy=FindFirstObjectByType<EnemyPatrol>();Check(enemy!=null,"E1 fixture exists");var ec=enemy.GetComponent<BoxCollider2D>();Vector2 es=ec.size,eo=ec.offset;Vector3 eScale=enemy.transform.localScale;yield return new WaitForSeconds(.1f);Check(ec.size==es&&ec.offset==eo&&enemy.transform.localScale==eScale,"enemy collider/transform unchanged by presentation");enemy.ReceiveHit(enemy.HP,Player.transform.position);yield return new WaitForSeconds(.15f);
  Check(Health.TakeDamage(1,Player.transform.position+Vector3.left),"hurt fixture");yield return new WaitForSeconds(Health.tuning.invincibility+.05f);yield return Enter("A03","FromRight");var cp=FindFirstObjectByType<Checkpoint>();Check(cp!=null,"checkpoint fixture exists");RoomSession.Instance.ActivateCheckpoint(cp);yield return null;
  if(av!=null){int before=Total(av);yield return Tap(Key.Escape);Check(GameState.GetOrCreate().Paused,"Pause input");foreach(var s in av.profile.sounds)Check(!av.Play(s.eventName),"Pause blocks "+s.eventName);yield return new WaitForSecondsRealtime(.15f);Check(Total(av)==before,"Pause new sounds0");yield return Tap(Key.Escape);yield return new WaitForSeconds(.1f);Check(av.Play("jump")&&!av.Play("jump"),"duplicate same-event throttle");}
  Check(shape.size==size&&shape.offset==offset&&Player.transform.localScale==scale,"player collider/root size and offset diff0");if(av!=null)Check(Player.GetComponentsInChildren<Collider2D>().Length==Player.GetComponents<Collider2D>().Length,"visual children contain no collider");else Check(FindObjectsByType<PresentationVisual>(FindObjectsSortMode.None).Length==0,"basic visual additions0");
  Check(RoomSession.Instance.Die(),"death fixture");yield return Until(()=>RoomSession.Instance.Respawning,"respawn start");yield return Ready();yield return new WaitForSeconds(.1f);if(av!=null)Check(!Player.GetComponent<SpriteRenderer>().enabled&&Player.GetComponent<PresentationVisual>()!=null,"respawn keeps candidate visual only");yield return Enter("B02");yield return Enter("B03");yield return Enter("C04","CP-C04");yield return Enter("C06","FromLeft");var boss=FindFirstObjectByType<BossEncounter>();Check(!boss.tuning.extendedPatterns,"AV/basic baseline two-pattern boss");Place(new Vector2(11,1.81f));yield return Until(()=>boss.Fighting,"boss tell");yield return new WaitForSeconds(.15f);boss.ReceiveHit(boss.HP,Player.transform.position);yield return Until(()=>FindFirstObjectByType<EndingMenu>()!=null,"victory ending");
  if(av!=null){foreach(var s in av.profile.sounds){av.Plays.TryGetValue(s.eventName,out int count);lines.Add("MEASURE audio "+s.eventName+" clip="+s.clip.name+" plays="+count);Check(count>0,"event clip played "+s.eventName);}foreach(string id in new[]{"form-0","form-1","form-2","form-3","form-4","walk","jump","landing","afterimage","hurt","death","attack","fragments"})Check(av.Effects.ContainsKey(id),"effect "+id);}else{Check(PresentationBootstrap.Instance==null,"basic audio plays0");lines.Add("MEASURE basic presentation audio=0 visual=0");}
 }
}
#endif
